const sample = {
  "demo": true,
  "sku": "MUG-NAVY",
  "onHand": 3,
  "inbound": 0,
  "dailyVelocity": 2
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const sku = item.sku || 'SKU';
const onHand = Number(item.onHand || 0);
const inbound = Number(item.inbound || 0);
const velocity = Number(item.dailyVelocity || 1);
const coverDays = velocity === 0 ? 999 : Math.round(((onHand + inbound) / velocity) * 10) / 10;
let route = 'ok';
if (onHand <= 0) route = 'stockout';
else if (onHand <= 5) route = 'reorder';
else if (coverDays < 7) route = 'watch';
const record = { sku, onHand, inbound, velocity, coverDays, reorderQty: Math.max(5 * 4 - onHand, 0), title: 'Stock ' + sku };
return {
  summary: sku + ' has ' + onHand + ' on hand (' + coverDays + ' days of cover) — ' + route + '.',
  route,
  record,
  slackText: route.toUpperCase() + ' ' + sku + ' cover ' + coverDays + ' days',
  actions: [{ app: 'Sheets', operation: 'append', payload: record }],
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'low-inventory-alert',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
